package com.gk.jobhelper.service;
import com.gk.jobhelper.common.*;import com.gk.jobhelper.dto.*;import com.gk.jobhelper.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.*;import java.util.stream.Collectors;
@Service public class RecruitmentNoticeService {private final RecruitmentNoticeMapper mapper;private final RecruitmentAttachmentMapper attachmentMapper;private final RecruitmentPositionMapper positionMapper;private static final Set<String> STATUS=new HashSet<>(Arrays.asList("NEW","INTERESTED","FOLLOWING","IGNORED"));private static final Set<String> FILTER_STATUS=new HashSet<>(Arrays.asList("NEW","INTERESTED","FOLLOWING","IGNORED","UNREAD"));public RecruitmentNoticeService(RecruitmentNoticeMapper m,RecruitmentAttachmentMapper a,RecruitmentPositionMapper p){mapper=m;attachmentMapper=a;positionMapper=p;}public PageVO<RecruitmentNoticeVO> page(String status,String sourceCode,String keyword,int page,int size){if(status!=null&&!status.isEmpty()&&!FILTER_STATUS.contains(status))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"无效公告状态");int p=Math.max(1,page),s=Math.min(100,Math.max(1,size));String k=keyword==null||keyword.trim().isEmpty()?null:"%"+keyword.trim()+"%";return new PageVO<>(mapper.count(status,sourceCode,k),p,s,mapper.selectPage(status,sourceCode,k,(p-1)*s,s));}public RecruitmentNoticeVO detail(Long id){RecruitmentNoticeVO n=mapper.selectDetail(id);if(n==null)throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"招聘公告不存在: "+id);n.setAttachments(attachmentMapper.selectByNoticeId(id));n.setBodyHtml(RecruitmentBodyImages.proxy(n.getBodyHtml(),n.getNoticeUrl(),id));return n;}public void updateStatus(Long id,String status){detail(id);if(!STATUS.contains(status))throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"无效公告状态");mapper.updateStatus(id,status,LocalDateTime.now());}public void view(Long id){detail(id);mapper.markViewed(id,LocalDateTime.now());}@Transactional public void delete(List<Long> ids){List<Long> valid=ids==null?Collections.emptyList():ids.stream().filter(Objects::nonNull).distinct().collect(Collectors.toList());if(valid.isEmpty())throw new BusinessException(ApiResponse.CODE_BAD_REQUEST,"请选择要删除的公告");positionMapper.deleteMatchItemsByNoticeIds(valid);positionMapper.deleteMatchResultsByNoticeIds(valid);positionMapper.deleteByNoticeIds(valid);attachmentMapper.deleteByNoticeIds(valid);mapper.deleteByIds(valid);}}
